def stable_dedupe(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

This assumes every item is hashable. If unhashable items must be supported, the contract and algorithm need to change.

def chunks(sequence, size):
    if size <= 0:
        raise ValueError("size must be positive")
    for start in range(0, len(sequence), size):
        yield sequence[start:start + size]

This version requires a sized, sliceable sequence; a general iterator needs a different implementation.

function parseJsonOr(value, fallback) {
  try {
    return JSON.parse(value);
  } catch (error) {
    if (error instanceof SyntaxError) return fallback;
    throw error;
  }
}

JSON.parse normally reports invalid JSON as SyntaxError. Keep the catch narrow and do not use this helper to validate the parsed value's shape.

type Shape = { kind: "circle"; radius: number } | { kind: "square"; side: number };
function assertNever(value: never): never {
  throw new Error(`Unhandled variant: ${JSON.stringify(value)}`);
}
function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.radius ** 2;
    case "square": return shape.side ** 2;
    default: return assertNever(shape);
  }
}

def lower_bound(sorted_values, target):
    left, right = 0, len(sorted_values)
    while left < right:
        mid = left + (right - left) // 2
        if sorted_values[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

The input must be sorted in ascending order under the same comparison relation.

from collections import Counter

def most_frequent(values):
    if not values:
        raise ValueError("values must not be empty")
    counts = Counter(values)
    highest = max(counts.values())
    return min(value for value, count in counts.items() if count == highest)

Counting is O(n) expected time, then selecting the tied minimum costs O(u) where u is the number of distinct strings; overall O(n + u), with O(u) extra space.
